def find_lexicographically_smallest_permutation(N, A):
    # Apply the left shift operation to find the lexicographically smallest permutation
    min_permutation = list(A)
    for _ in range(N):
        min_permutation = min_permutation[1:] + [min_permutation[0]]
        if min_permutation < A:
            A = min_permutation[:]

    # Try to improve the permutation with at most two swaps
    for i in range(N):
        for j in range(i + 1, N):
            for k in range(N):
                for l in range(k + 1, N):
                    new_permutation = A[:]
                    new_permutation[i], new_permutation[j] = new_permutation[j], new_permutation[i]
                    new_permutation[k], new_permutation[l] = new_permutation[l], new_permutation[k]
                    if new_permutation < A:
                        A = new_permutation[:]

    return A

def main():
